/** Fixed donors can leave declared universal variables in a checked native residual head. */
public final class ContextUniversalSymbolicHeadApplicationsRunner {
    static int checks;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static Snapshot bind(boolean x,String s)throws Exception{return ContextPrivateWitnessPoolRunner.bind(x,s);}
    static ContextUniversalNativeRows.Result rows(Snapshot x,Snapshot a){ContextUniversalNativeRows.Result r=ContextUniversalNativeRows.inspect(x,a,64,WORK);require(r.classified&&r.withinShape,r.reason);return r;}
    static Result close(Snapshot x,Snapshot a,Packet common,PrivatePool pool,int depth){Result r=ContextUniversalFrozenConstraints.closeSignedSymbolicHeads(rows(x,a),common,pool,null,16,depth,512,256,WORK);require(r.closed&&r.symbolicHeads&&r.signedApplications,r.reason);ContextUniversalFrozenConstraints.check(r,depth,()->{});Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Proof p:r.proofs)audit(p,seen);return r;}
    static void audit(Proof p,Set<Proof> seen){if(!seen.add(p))return;require(p.exchanged==null,"no imported owning frame in this checked/flattened DAG");if(p.original!=null){require(p.original.parts.contains(p.part)&&p.support.depth==0&&p.support.sources.equals(Collections.singleton(p.original.original.source)),"actual whole original Source0");return;}if(p.input!=null){require(p.input.proofs.contains(p.inputProof)&&p.support.equals(p.inputProof),"actual carried Item/Support grade");return;}Set<Source> sources=new HashSet<>();int depth;Residual expected;
        if(p.producer!=null){audit(p.producer,seen);depth=p.producer.support.depth;sources.addAll(p.producer.support.sources);List<Residual> donors=new ArrayList<>();for(Proof donor:p.donors){audit(donor,seen);require(donor.clause.variables.isEmpty(),"actual application donors remain fixed");donors.add(donor.clause);depth=Math.max(depth,donor.support.depth);sources.addAll(donor.support.sources);}expected=p.symbolicHeadRecipe?ContextUniversalInputResiduals.applySymbolicHeadFixedUnits(p.producer.clause,p.conclusion,donors,()->{}):p.conclusion<0?ContextUniversalInputResiduals.applyFixedPositiveUnits(p.producer.clause,donors,()->{}):ContextUniversalInputResiduals.applyFixedSignedUnits(p.producer.clause,p.conclusion,donors,()->{});}
        else{audit(p.unit,seen);audit(p.horn,seen);depth=Math.max(p.unit.support.depth,p.horn.support.depth);sources.addAll(p.unit.support.sources);sources.addAll(p.horn.support.sources);expected=ContextUniversalInputResiduals.resolveSignedUnit(p.unit.clause,p.horn.clause,p.pivot,()->{});}
        require(p.clause==null?expected==null:expected!=null&&p.clause.equivalent(expected,()->{}),"independent typed recipe replay");require(p.support.sources.equals(sources)&&p.support.depth==depth+1,"all parent Sources and max-parent+1 preserved");
    }
    static Proof unit(Result r,String name,boolean sign){return r.proofs.stream().filter(p->p.clause!=null&&p.clause.literals.size()==1&&p.clause.literals.get(0).predicate.equals(name)&&p.clause.literals.get(0).positive==sign).findFirst().get();}
    static Map<Cut,Result> cuts(Snapshot x,Snapshot a,Packet p,PrivatePool pool,int depth){Map<Cut,Result> r=new LinkedHashMap<>();r.put(Cut.of(x),close(x,null,p,null,depth));r.put(Cut.of(a),close(x,a,p,pool,depth));return r;}
    static ContextUniversalSignedUnitExchange.Exchange collect(Snapshot x,Packet p,Map<Cut,Result> checks,int depth){ContextUniversalSignedUnitExchange.Collection c=ContextUniversalSignedUnitExchange.collect(x,p,new ArrayList<>(checks.keySet()),checks,512,256,depth,WORK);require(c.collected,c.reason);return c.output;}
    static void nativeAndTransfer()throws Exception {
        String rule="!@x @y p(x)&&q(x)->~r(y);",p="!p(1);",q="!q(1);";Snapshot x=bind(true,p+q),a=bind(false,rule);Packet common=ContextPrivateWitnessPoolRunner.common(x);Result old=ContextUniversalFrozenConstraints.closeSignedFixedApplications(rows(x,a),common,null,null,16,16,512,256,WORK);require(old.closed&&!old.symbolicHeads&&unit(old,"r",false).support.depth==2,"old fixed-conclusion mode keeps symbolic2");Result r=close(x,a,common,null,1);Proof produced=unit(r,"r",false);require(produced.symbolicHeadRecipe&&produced.producer!=null&&produced.clause.variables.size()==1&&produced.support.depth==1&&produced.support.sources.size()==3,"genuine universal negative1 with complete three Sources");
        User user=new User();Mind mind=new Mind(user);user.setCurrentMind(mind);try(ContextProductionCapture capture=ContextProductionCapture.begin(mind,10000)){capture.replay(mind,ContextPrivateWitnessPoolRunner.source(a,rule),rule);capture.replay(mind,ContextPrivateWitnessPoolRunner.source(x,p),p);capture.replay(mind,ContextPrivateWitnessPoolRunner.source(x,q),q);mind.setQueryPass(QueryPass.ACCEPT);mind.link(null,false);ContextProductionCapture.Snapshot observed=capture.snapshot();require(observed.gaps.isEmpty(),"native residual capture has no gaps");boolean found=false;for(ContextProductionCapture.Residual e:observed.residuals)if(e.conclusion.literals.size()==1&&e.conclusion.literals.get(0).predicate.equals("r")&&e.premises.size()==2){require(e.steps==1&&e.conclusion.variables.size()==1&&produced.clause.equivalent(ContextUniversalInputResiduals.schema(e.conclusion,()->{}),()->{}),"actual native symbolic residual and one-step grade agree");for(Proof donor:produced.donors)require(e.premises.stream().anyMatch(f->donor.clause.equivalent(ContextUniversalInputResiduals.fact(f,()->{}),()->{})),"same actual fixed donor group");require(e.producerSupports.stream().anyMatch(s->s.depth==0&&s.sources.equals(produced.producer.support.sources)),"same original native producer Source0");found=true;}require(found,"actual native two-donor symbolic unit observed");}
        Map<Cut,Result> all=cuts(x,a,common,null,1);ContextUniversalSignedUnitExchange.Exchange exchange=collect(x,common,all,1);require(exchange.units.stream().anyMatch(u->u.clause.equivalent(produced.clause,()->{})&&u.support.equals(produced.support)),"symbolic output collected at fact bound1");ContextUniversalSignedUnitExchange.Collection denied=ContextUniversalSignedUnitExchange.collect(x,common,new ArrayList<>(all.keySet()),all,512,256,0,WORK);require(!denied.collected&&denied.output==null,"symbolic bound0 no output prefix");
        ConstraintTransfer fixed=ContextWitnessResultTransport.transferConstraints(r,common,0,WORK);require(fixed.transferred&&fixed.output.items.size()==2&&ContextUniversalSignedProductAudit.bind(r,fixed,65536,WORK).bound,"fixed projection never samples universal r or falsely claims symbolic bound coverage");
        Snapshot opinion=bind(false,"!r(987654);");Result consumer=ContextUniversalFrozenConstraints.closeSignedUnits(rows(x,opinion),common,null,exchange,16,16,512,256,WORK);require(consumer.closed&&consumer.xRefuted&&!consumer.symbolicHeads,consumer.reason);require(consumer.emptyProofs.stream().anyMatch(v->v.support.depth==2&&v.support.sources.size()==4),"universal applies to previously unmentioned value, empty2/full four Sources");Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Proof proof:ContextUniversalFrozenConstraints.rejectionEvidence(consumer,WORK))audit(proof,seen);require(seen.stream().anyMatch(v->v.symbolicHeadRecipe&&!v.clause.variables.isEmpty()),"flattened imported proof keeps symbolic recipe without owner frame");
        Result limited=ContextUniversalFrozenConstraints.closeSignedSymbolicHeads(rows(x,a),common,null,null,1,16,512,256,WORK);require(!limited.closed&&limited.proofs.isEmpty(),"round limit hides partial proofs");limited=ContextUniversalFrozenConstraints.closeSignedSymbolicHeads(rows(x,a),common,null,null,16,16,512,256,1);require(!limited.closed&&limited.proofs.isEmpty(),"work cap no partial state");
    }
    static void originsAndBindings()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@u @v p(u,1)&&q(u,1)->~r(u,v);"),a=bind(false,"!$u p(u,1)&&q(u,1);");Packet common=ContextPrivateWitnessPoolRunner.common(x);PrivatePool pool=ContextWitnessResultTransport.privatePool(common,x,a,WORK);Result r=close(x,a,common,pool,1);Proof negative=unit(r,"r",false);require(negative.clause.variables.size()==1&&negative.clause.origins.size()==1&&negative.support.depth==1&&negative.support.sources.size()==2,"mixed rigid Origin and universal variable remain distinct");require(negative.clause.origins.iterator().next().source.equals(a.primary.get(0).source),"original physical binding preserved");Map<Cut,Result> all=cuts(x,a,common,pool,1);ContextUniversalSignedUnitExchange.Exchange exchange=collect(x,common,all,1);
        Snapshot opinion=bind(false,"!@u @v r(u,v);");Result consumer=ContextUniversalFrozenConstraints.closeSignedUnits(rows(x,opinion),common,null,exchange,16,16,512,256,WORK);require(consumer.closed&&consumer.xRefuted&&consumer.emptyProofs.stream().anyMatch(v->v.support.depth==2&&v.support.sources.size()==3&&v.support.sources.contains(a.primary.get(0).source)),"actual private binding Source authenticates imported universal collision");Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Proof proof:ContextUniversalFrozenConstraints.rejectionEvidence(consumer,WORK))audit(proof,seen);
        Snapshot split=bind(false,"!$u p(u,1); !$u q(u,1);");PrivatePool separate=ContextWitnessResultTransport.privatePool(common,x,split,WORK);Result independent=close(x,split,common,separate,16);require(independent.proofs.stream().noneMatch(v->v.clause!=null&&v.clause.literals.size()==1&&v.clause.literals.get(0).predicate.equals("r")),"different Origins cannot become one universal binding");
        Snapshot crossed=bind(true,"!p(1); !q(2);"),rule=bind(false,"!@x @y p(x)&&q(x)->~r(y);");Result bad=close(crossed,rule,ContextPrivateWitnessPoolRunner.common(crossed),null,16);require(bad.proofs.stream().noneMatch(v->v.clause!=null&&v.clause.literals.size()==1&&v.clause.literals.get(0).predicate.equals("r")),"fixed donor bindings must agree even with a symbolic head");
    }
    static void alternativesAndScope()throws Exception {
        Snapshot x=bind(true,"!p(1); !q(1);"),a=bind(false,"!@x @y p(x)&&q(x)->~r(y);"),loop=bind(false,"!@x r(x)->r(x);");Snapshot group=ContextProductionNativeBinding.trusted("own",Arrays.asList(a,loop),WORK);Packet common=ContextPrivateWitnessPoolRunner.common(x);Result r=close(x,group,common,null,16);List<Proof> alternatives=new ArrayList<>();for(Proof proof:r.proofs)if(proof.clause!=null&&proof.clause.literals.size()==1&&proof.clause.literals.get(0).predicate.equals("r"))alternatives.add(proof);require(alternatives.size()==2&&alternatives.stream().anyMatch(v->v.support.depth==1&&v.support.sources.size()==3)&&alternatives.stream().anyMatch(v->v.support.depth==2&&v.support.sources.size()==4),"symbolic Source superset keeps separate deeper minimum");Map<Cut,Result> all=cuts(x,group,common,null,16);ContextUniversalSignedUnitExchange.Collection tooShort=ContextUniversalSignedUnitExchange.collect(x,common,new ArrayList<>(all.keySet()),all,512,256,1,WORK);require(!tooShort.collected&&tooShort.output==null,"shorter different-Source symbolic proof cannot hide deeper alternative");collect(x,common,all,2);
        Snapshot symbolic=bind(true,"!anchor(1); !@x p(x); !@x q(x);"),consumer=bind(false,"!@x p(x)&&q(x)->~r(x);");Result oldBoundary=close(symbolic,consumer,ContextPrivateWitnessPoolRunner.common(symbolic),null,16);Proof out=unit(oldBoundary,"r",false);require(!out.symbolicHeadRecipe&&out.support.depth==2,"symbolic donors remain binary, no unproved simultaneous grade1");
        Snapshot positiveX=bind(true,"!p(1); !q(1); !@x a(x);"),positive=bind(false,"!@x @y a(x)&&p(y)&&q(y)->r(x);");Result general=close(positiveX,positive,ContextPrivateWitnessPoolRunner.common(positiveX),null,16);Proof positiveHead=unit(general,"r",true);require(positiveHead.symbolicHeadRecipe&&positiveHead.support.depth==2&&positiveHead.clause.variables.size()==1&&positiveHead.producer.support.depth==1,"checked producer residual can keep positive universal head; symbolic donor still costs binary step");
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("symbolic-head-applications-").toString());nativeAndTransfer();originsAndBindings();alternativesAndScope();System.out.println("CONTEXT_UNIVERSAL_SYMBOLIC_HEAD_APPLICATIONS_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
